+let
+  cfg = config.services.opengist;
+  settingsFormat = pkgs.formats.yaml { };
+  settingsFile = settingsFormat.generate "opengist-settings" cfg.settings;
+
+  inherit (lib)
+    concatStringsSep
+    getExe
+    mkEnableOption
+    mkIf
+    mkOption
+    mkPackageOption
+    ;
+  inherit (lib.types)
+    bool
+    enum
+    listOf
+    int
+    nullOr
+    oneOf
+    path
+    str
+    submodule
+    ;
+in
+{
+  options.services.opengist = {
+    enable = mkEnableOption "opengist";
+
+    package = mkPackageOption pkgs "opengist" { };
+
+    environmentFile = mkOption {
+      type = nullOr path;
+      default = null;
+      description = ''
+        File to load as environment file.
+        See https://github.com/thomiceli/opengist/blob/master/docs/configuration/cheat-sheet.md for variable names and description.
+        Some options can be configured through both the config file (via this module) and the environment. Conflict between those two is undocumented.
+      '';
+    };
+
+    settings = mkOption {
+      # note to myself follow https://github.com/thomiceli/opengist/blob/master/config.yml
+      type = submodule {
+        freeformType = settingsFormat.type;
+        options = {
+          /*
+            Most options are also available via the environmentFile.
+            Opengist will set itself default values if set to null.
+            It's better to set the default as null rather than a normal default value in case the user wants to modify the option with the environmentFile (the conflict between those two is undocumented).
+          */
+
+          log-level = mkOption {
+            type = nullOr (enum [
+              "debug"
+              "info"
+              "warn"
+              "error"
+              "fatal"
+            ]);
+            default = null;
+            description = ''
+              Set the log level.
+              When set to null, will default to "warn".
+              You can also set this option via $OG_LOG_LEVEL in `services.opengist.environmentFile`.
+            '';
+          };
+
+          log-output = mkOption {
+            type = nullOr (enum [
+              "stdout"
+              "file"
+              "stdout,file"
+            ]);
+            default = null;
+            description = ''
+              Set the destination of the log output.
+              When set to null, will default to "stdout,file"
+              You can also set this option via $OG_LOG_OUTPUT in `services.opengist.environmentFile`.
+            '';
+          };
+
+          log-path = mkOption {
+            type = nullOr path;
+            default = null;
+            description = ''
+              Set the directory where the log file (opengist.log) is written.
+              When set to null, will default to $OG_OPENGIST_HOME/log.
+              $OG_OPENGIST_HOME can be set with the with the environment file (`services.opengist.environmentFile`) or with the option `services.opengist.settings.opengist-home`.
+              You can also set this option via $OG_LOG_PATH in `services.opengist.environmentFile`.
+            '';
+          };
+

